@ParameterizedTest
    @CsvSource({
        "0, 0",
        "1.960, 0.95",
        "2.576, 0.99",
        "2.807, 0.995",
        "3.291, 0.999",
    })
    void testErf_1_oe(double x, double expected) {
        // Input must be divided by root(2)
        x /= Math.sqrt(2);

        double actual = Erf.value(x);
        Assertions.assertEquals(expected, actual, 1e-5);
        }

